const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体' },
      { kind: 'text', payload: '由静止释放' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v、g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cx = w * 0.42;
    var cy = h * 0.30;
    var r = Math.max(14, Math.min(w, h) * 0.075);
    var startY = cy + r + 10;
    var vx = cx - r * 1.5;
    var gx = cx + r * 1.5;
    var vLen = h * 0.26;
    var gLen = h * 0.21;
    var vEndY = startY + vLen;
    var gEndY = startY + gLen;
    var ball = visualSdk.circle(cx, cy, r);
    var vArrow = visualSdk.arrow(vx, startY, vx, vEndY, {});
    var gArrow = visualSdk.arrow(gx, startY, gx, gEndY, {});
    return {
      schemaVersion: 1,
      sceneId: 'freefall-schematic',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'ball', commands: ball },
        { id: 'vArrow', commands: vArrow },
        { id: 'gArrow', commands: gArrow }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ball', stroke: '#26354a', strokeWidth: 2.5, fill: '#dbe7f7' },
          { type: 'path', pathId: 'vArrow', stroke: '#1f6feb', strokeWidth: 2.5 },
          { type: 'path', pathId: 'gArrow', stroke: '#d9480f', strokeWidth: 2.5 },
          { type: 'label', text: '自由落体', x: w / 2, y: 30, anchor: 'middle', fontSize: 20, fill: '#26354a' },
          { type: 'label', text: '由静止释放', x: cx, y: cy - r - 14, anchor: 'middle', fontSize: 15, fill: '#26354a' },
          { type: 'label', text: 'v', x: vx - 12, y: startY + vLen / 2 + 5, anchor: 'end', fontSize: 20, fill: '#1f6feb' },
          { type: 'label', text: 'g', x: gx + 12, y: startY + gLen / 2 + 5, anchor: 'start', fontSize: 20, fill: '#d9480f' },
          { type: 'label', text: 'v、g 均竖直向下', x: w / 2, y: h - 24, anchor: 'middle', fontSize: 14, fill: '#26354a' }
        ]
      }
    };
  }
};
